function solve(elapsedHours, extension) {
  // Assumed policy: a 24-hour grant, extended once by at most 24 hours
  // by an incident commander, with approval recorded before the grant expires.
  const baseHours = 24;
  let expiresAt = baseHours;

  if (
    extension !== null &&
    typeof extension === 'object' &&
    !Array.isArray(extension) &&
    extension.approver === 'incident-commander' &&
    Number.isFinite(extension.addedHours) &&
    extension.addedHours >= 0 &&
    extension.addedHours <= 24 &&
    Number.isFinite(extension.recordedAt) &&
    extension.recordedAt >= 0 &&
    extension.recordedAt < baseHours &&
    extension.recordedAt <= elapsedHours
  ) {
    expiresAt += extension.addedHours;
  }

  return elapsedHours < expiresAt;
}
